// ── ICE KINGDOM — Frozen mountain castle, northern lights, snowman ──
// mt, w1, w2, w3, w, h, bY, bCol, wc, ol, isN, sc — runtime

// Sky gradient
svg += `<defs>
  <linearGradient id="lg-ice" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN ? '#06001A' : sc.sky1}"/>
    <stop offset="50%" stop-color="${isN ? '#0D0B3E' : '#4A78A8'}"/>
    <stop offset="100%" stop-color="${isN ? '#1A1A4A' : sc.sky2}"/>
  </linearGradient>
  <linearGradient id="lg-ice-mtn" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#D8E8F8"/>
    <stop offset="100%" stop-color="#A0C0D8"/>
  </linearGradient>
  <linearGradient id="lg-ice-castle" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN ? '#8EC8F8' : '#C8E8FF'}"/>
    <stop offset="100%" stop-color="${isN ? '#5A8AB8' : '#90C0E0'}"/>
  </linearGradient>
  <radialGradient id="rg-ice-glow">
    <stop offset="0%" stop-color="rgba(125,249,255,0.3)"/>
    <stop offset="100%" stop-color="rgba(125,249,255,0)"/>
  </radialGradient>
</defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-ice)"/>`;

// ── Northern Lights (aurora borealis) ──
for (let i = 0; i < 5; i++) {
  const ax = w * (0.1 + i * 0.18);
  const ay = h * 0.08 + Math.sin(mt * 0.4 + i * 1.2) * h * 0.06;
  const aw = w * 0.22;
  const ah = h * 0.25 + Math.sin(mt * 0.3 + i * 0.8) * h * 0.05;
  const aop = 0.06 + Math.sin(mt * 0.5 + i * 0.97) * 0.04;
  const colors = ['#00FF88','#7DF9FF','#DA70D6','#00CED1','#9370DB'];
  svg += `<ellipse cx="${ax}" cy="${ay}" rx="${aw}" ry="${ah}" fill="${colors[i]}" opacity="${aop}"/>`;
}
// Aurora curtain waves
for (let i = 0; i < 3; i++) {
  const cy = h * 0.12 + i * h * 0.04;
  const sway = Math.sin(mt * 0.6 + i * 1.5) * w * 0.05;
  svg += `<path d="M0 ${cy} Q${w*0.2+sway} ${cy-15} ${w*0.4} ${cy+5} T${w*0.7} ${cy-8} T${w} ${cy}" fill="none" stroke="rgba(125,249,255,${0.12 + Math.sin(mt*0.4+i)*0.06})" stroke-width="${3+i}"/>`;
}

// ── Stars (night enhancement) ──
for (let i = 0; i < 40; i++) {
  const sx = (Math.sin(i * 127.1 + 3.7) * 0.5 + 0.5) * w;
  const sy = (Math.sin(i * 311.7 + 1.3) * 0.5 + 0.5) * h * 0.4;
  const sr = 0.5 + Math.sin(mt * 1.2 + i * 0.9) * 0.5;
  const sop = isN ? 0.7 + Math.sin(mt + i * 0.5) * 0.3 : 0.15 + Math.sin(mt + i) * 0.1;
  svg += `<circle cx="${sx}" cy="${sy}" r="${sr}" fill="#FFF" opacity="${sop}"/>`;
}

// ── Distant snow mountains (background) ──
svg += `<path d="M0 ${bY+10} Q${w*0.08} ${bY-60} ${w*0.18} ${bY-100} Q${w*0.25} ${bY-130} ${w*0.32} ${bY-90} Q${w*0.4} ${bY-40} ${w*0.5} ${bY+10}" fill="url(#lg-ice-mtn)" stroke="#C0D8E8" stroke-width="${ol*0.5}" opacity="0.5"/>`;
svg += `<path d="M${w*0.55} ${bY+10} Q${w*0.65} ${bY-50} ${w*0.72} ${bY-80} Q${w*0.78} ${bY-110} ${w*0.85} ${bY-70} Q${w*0.92} ${bY-30} ${w} ${bY+10}" fill="url(#lg-ice-mtn)" stroke="#C0D8E8" stroke-width="${ol*0.5}" opacity="0.4"/>`;

// ── Main mountain with ice castle ──
const mtnX = w * 0.5;
const mtnH = 180 + w2 * 15;
svg += `<path d="M${mtnX-180} ${bY} Q${mtnX-80} ${bY-mtnH*0.6} ${mtnX} ${bY-mtnH} Q${mtnX+80} ${bY-mtnH*0.6} ${mtnX+180} ${bY} Z" fill="#C8DAE8" stroke="#A0B8D0" stroke-width="${ol}"/>`;
// Snow cap
svg += `<path d="M${mtnX-40} ${bY-mtnH*0.75} Q${mtnX} ${bY-mtnH} ${mtnX+40} ${bY-mtnH*0.75}" fill="#F0F8FF" stroke="none"/>`;
// Snow streaks
for (let i = 0; i < 4; i++) {
  const sx2 = mtnX - 60 + i * 35;
  const sy2 = bY - mtnH * (0.4 + i * 0.1);
  svg += `<line x1="${sx2}" y1="${sy2}" x2="${sx2+15}" y2="${sy2+25}" stroke="#F0F8FF" stroke-width="2" opacity="0.4"/>`;
}

// ── ICE CASTLE ──
const cx = mtnX;
const cy = bY - mtnH - 10;

// Castle main body
svg += `<rect x="${cx-35}" y="${cy}" width="70" height="55" rx="3" fill="url(#lg-ice-castle)" stroke="#80B0D0" stroke-width="${ol}"/>`;
// Castle gate (large arched door)
svg += `<path d="M${cx-10} ${cy+55} L${cx-10} ${cy+35} Q${cx} ${cy+25} ${cx+10} ${cy+35} L${cx+10} ${cy+55}" fill="${isN ? 'rgba(125,249,255,0.4)' : 'rgba(100,180,220,0.3)'}" stroke="#80B0D0" stroke-width="${ol*0.5}"/>`;

// Left tower
svg += `<rect x="${cx-55}" y="${cy-40}" width="24" height="95" rx="2" fill="url(#lg-ice-castle)" stroke="#80B0D0" stroke-width="${ol}"/>`;
svg += `<polygon points="${cx-55},${cy-40} ${cx-43},${cy-65} ${cx-31},${cy-40}" fill="#A0D8F0" stroke="#80B0D0" stroke-width="${ol*0.7}"/>`;

// Right tower (taller)
svg += `<rect x="${cx+31}" y="${cy-55}" width="24" height="110" rx="2" fill="url(#lg-ice-castle)" stroke="#80B0D0" stroke-width="${ol}"/>`;
svg += `<polygon points="${cx+31},${cy-55} ${cx+43},${cy-85} ${cx+55},${cy-55}" fill="#A0D8F0" stroke="#80B0D0" stroke-width="${ol*0.7}"/>`;

// Castle windows with magical glow
const windowPositions = [[-43,cy-20],[-43,cy+10],[cx-15-cx+cx,cy+10],[cx+15-cx+cx,cy+10],[43,cy-35],[43,cy-5],[43,cy+25]];
for (let i = 0; i < 7; i++) {
  const wp = windowPositions[i];
  const wxp = cx + wp[0];
  const wyp = wp[1];
  const pulse = Math.sin(mt * 1.8 + i * 1.3) * 0.5 + 0.5;
  svg += `<rect x="${wxp-3}" y="${wyp}" width="6" height="8" rx="3" fill="rgba(125,249,255,${0.4 + pulse * 0.5})" stroke="#80B0D0" stroke-width="${ol*0.3}"/>`;
  if (isN) svg += `<ellipse cx="${wxp}" cy="${wyp+4}" rx="10" ry="8" fill="rgba(125,249,255,${0.03 + pulse * 0.04})"/>`;
}

// Castle magical glow
const glowR = 40 + w3 * 15;
svg += `<circle cx="${cx}" cy="${cy-10}" r="${glowR}" fill="url(#rg-ice-glow)"/>`;

// ── Frozen ground / snow field ──
svg += `<path d="M0 ${bY} Q${w*0.15} ${bY-8} ${w*0.3} ${bY+3} Q${w*0.5} ${bY-5} ${w*0.7} ${bY+5} Q${w*0.85} ${bY-3} ${w} ${bY} L${w} ${h} L0 ${h} Z" fill="${sc.ground}" stroke="#C0D8F0" stroke-width="${ol*0.5}"/>`;
// Sparkle highlights on snow
for (let i = 0; i < 12; i++) {
  const spx = w * (0.05 + i * 0.08);
  const spy = bY + 5 + Math.sin(i * 2.1) * 8;
  const spop = 0.3 + Math.sin(mt * 2.5 + i * 1.7) * 0.3;
  svg += `<circle cx="${spx}" cy="${spy}" r="1.5" fill="#FFF" opacity="${spop}"/>`;
}

// ── Frozen lake ──
const lakeX = w * 0.18;
const lakeY = bY + 15;
svg += `<ellipse cx="${lakeX}" cy="${lakeY}" rx="${w*0.12}" ry="18" fill="${isN ? '#2A4A6A' : '#8BC8E8'}" stroke="#A0C8E0" stroke-width="${ol*0.4}" opacity="0.7"/>`;
// Ice reflection shimmer
for (let i = 0; i < 4; i++) {
  const rx = lakeX - w*0.08 + i * w * 0.05;
  const rop = 0.2 + Math.sin(mt * 1.5 + i * 1.1) * 0.15;
  svg += `<line x1="${rx}" y1="${lakeY-5}" x2="${rx+12}" y2="${lakeY-3}" stroke="#FFF" stroke-width="1" opacity="${rop}"/>`;
}

// ── SNOWMAN ──
const smx = w * 0.72;
const smy = bY - 2;
// Bottom ball
svg += `<circle cx="${smx}" cy="${smy}" r="16" fill="#F8F8FF" stroke="#C8D8E8" stroke-width="${ol*0.6}"/>`;
// Middle ball
svg += `<circle cx="${smx}" cy="${smy-26}" r="12" fill="#F8F8FF" stroke="#C8D8E8" stroke-width="${ol*0.6}"/>`;
// Head
svg += `<circle cx="${smx}" cy="${smy-46}" r="9" fill="#F8F8FF" stroke="#C8D8E8" stroke-width="${ol*0.6}"/>`;
// Eyes
svg += `<circle cx="${smx-3}" cy="${smy-48}" r="1.5" fill="#2A2A2A"/>`;
svg += `<circle cx="${smx+3}" cy="${smy-48}" r="1.5" fill="#2A2A2A"/>`;
// Carrot nose
svg += `<polygon points="${smx},${smy-45} ${smx+8},${smy-44} ${smx},${smy-43}" fill="#FF8C42"/>`;
// Smile
svg += `<path d="M${smx-4} ${smy-41} Q${smx} ${smy-39} ${smx+4} ${smy-41}" fill="none" stroke="#2A2A2A" stroke-width="1"/>`;
// Buttons
for (let i = 0; i < 3; i++) svg += `<circle cx="${smx}" cy="${smy-20+i*7}" r="1.5" fill="#2A2A2A"/>`;
// Twig arms (swaying with wind)
const armSway = Math.sin(mt * 0.8) * 5;
svg += `<line x1="${smx-12}" y1="${smy-28}" x2="${smx-28}" y2="${smy-38+armSway}" stroke="#6B4F2A" stroke-width="2" stroke-linecap="round"/>`;
svg += `<line x1="${smx+12}" y1="${smy-28}" x2="${smx+28}" y2="${smy-40-armSway}" stroke="#6B4F2A" stroke-width="2" stroke-linecap="round"/>`;
// Top hat
svg += `<rect x="${smx-7}" y="${smy-60}" width="14" height="12" rx="1" fill="#2A2A3A" stroke="#1A1A2A" stroke-width="${ol*0.4}"/>`;
svg += `<rect x="${smx-10}" y="${smy-49}" width="20" height="3" rx="1" fill="#2A2A3A"/>`;

// ── Ice bridge (foreground) ──
const bridgeY2 = bY + 20;
svg += `<path d="M0 ${bridgeY2+10} Q${w*0.15} ${bridgeY2-8} ${w*0.3} ${bridgeY2+5} Q${w*0.45} ${bridgeY2-5} ${w*0.6} ${bridgeY2+8}" fill="none" stroke="rgba(160,200,220,0.4)" stroke-width="4"/>`;

// ── Princess silhouette on the bridge ──
const px = w * 0.35;
const py = bY + 2;
// Dress (triangle shape)
svg += `<polygon points="${px},${py-25} ${px-12},${py} ${px+12},${py}" fill="${isN ? '#6A5ACD' : '#87CEEB'}" stroke="${isN ? '#483D8B' : '#5F9EA0'}" stroke-width="${ol*0.5}" opacity="0.85"/>`;
// Cape flowing
const capeFlow = Math.sin(mt * 1.2) * 6;
svg += `<path d="M${px+3} ${py-22} Q${px+15+capeFlow} ${py-18} ${px+10+capeFlow*1.5} ${py-5}" fill="none" stroke="${isN ? '#9370DB' : '#ADD8E6'}" stroke-width="2.5" stroke-linecap="round" opacity="0.7"/>`;
// Head
svg += `<circle cx="${px}" cy="${py-30}" r="6" fill="#FFDAB9" stroke="#DEB887" stroke-width="${ol*0.3}"/>`;
// Hair braid (with wind sway)
const braidSway = Math.sin(mt * 0.9) * 3;
svg += `<path d="M${px+4} ${py-28} Q${px+10+braidSway} ${py-18} ${px+8+braidSway*1.2} ${py-8}" fill="none" stroke="#F5DEB3" stroke-width="3" stroke-linecap="round"/>`;
// Crown/tiara
svg += `<path d="M${px-5} ${py-35} L${px-3} ${py-39} L${px} ${py-36} L${px+3} ${py-39} L${px+5} ${py-35}" fill="none" stroke="${sc.acc}" stroke-width="1.5"/>`;
// Magic sparkle from hand
const sparkleR = 3 + w3 * 4;
const sparkleOp = 0.4 + w1 * 0.4;
svg += `<circle cx="${px-14}" cy="${py-12}" r="${sparkleR}" fill="${sc.acc}" opacity="${sparkleOp * 0.3}"/>`;
svg += `<circle cx="${px-14}" cy="${py-12}" r="${sparkleR*0.4}" fill="#FFF" opacity="${sparkleOp}"/>`;
// Magic trail particles
for (let i = 0; i < 6; i++) {
  const mpx = px - 14 + Math.sin(mt * 2 + i * 1.05) * (10 + i * 4);
  const mpy = py - 12 + Math.cos(mt * 1.8 + i * 0.8) * (8 + i * 3);
  const mpr = 1 + Math.sin(mt * 3 + i * 1.3) * 0.8;
  svg += `<circle cx="${mpx}" cy="${mpy}" r="${mpr}" fill="${sc.acc}" opacity="${0.3 + Math.sin(mt*2+i)*0.3}"/>`;
}

// ── Pine trees (snow-covered) ──
for (let i = 0; i < 5; i++) {
  const tx = w * 0.82 + i * 22;
  const th = 25 + Math.sin(i * 1.7) * 8;
  const treeSway = Math.sin(mt * 0.5 + i * 0.9) * 1.5;
  svg += `<line x1="${tx}" y1="${bY}" x2="${tx+treeSway}" y2="${bY-th}" stroke="#2E4A2A" stroke-width="3"/>`;
  for (let j = 0; j < 3; j++) {
    const ty = bY - th + j * (th * 0.3);
    const tw2 = 6 + j * 4;
    svg += `<polygon points="${tx+treeSway},${ty} ${tx-tw2+treeSway*0.5},${ty+th*0.25} ${tx+tw2+treeSway*0.5},${ty+th*0.25}" fill="#2E5A3A" stroke="#1A3A20" stroke-width="${ol*0.3}"/>`;
    // Snow on branches
    svg += `<line x1="${tx-tw2*0.6+treeSway*0.5}" y1="${ty+th*0.25}" x2="${tx+tw2*0.6+treeSway*0.5}" y2="${ty+th*0.25}" stroke="#F0F8FF" stroke-width="2.5" stroke-linecap="round" opacity="0.7"/>`;
  }
}

// ── Animated snowflakes ──
for (let i = 0; i < 25; i++) {
  const sfx = (Math.sin(i * 73.1 + 5.3) * 0.5 + 0.5) * w + Math.sin(mt * 0.8 + i * 0.6) * 15;
  const sfy = ((mt * 8 + i * (h / 25)) % (h + 20)) - 10;
  const sfr = 1 + Math.sin(i * 2.3) * 0.8;
  const sfop = 0.4 + Math.sin(mt * 1.5 + i * 0.7) * 0.3;
  svg += `<circle cx="${sfx % w}" cy="${sfy}" r="${sfr}" fill="#FFF" opacity="${sfop}"/>`;
}

// ── Sun (day) / Moon (night) ──
if (!isN) {
  svg += `<circle cx="${w * 0.15}" cy="${h * 0.15}" r="${40 + w1 * 10}" fill="#FFF8E0" opacity="0.12"/>`;
  svg += `<circle cx="${w * 0.15}" cy="${h * 0.15}" r="20" fill="#FFF8E0" opacity="0.4"/>`;
} else {
  svg += `<circle cx="${w * 0.15}" cy="${h * 0.12}" r="16" fill="#EDE8DF" opacity="0.85"/>`;
  svg += `<circle cx="${w * 0.15 + 5}" cy="${h * 0.12 - 4}" r="13" fill="${isN ? '#06001A' : sc.sky2}" opacity="0.9"/>`;
  // Moonlight beam
  svg += `<ellipse cx="${w*0.15}" cy="${h*0.12}" rx="60" ry="40" fill="rgba(237,232,223,0.03)"/>`;
}
